// G3 golden-path smoke → Scorpion register (Watchdog already smokes this path).
// Daily OS = Grok Bot + Cursor. n8n is legacy webhook glue, not a second daily OS.
// Lane: hive-os. G1 Telegram is soft/legacy — this workflow does not send Telegram.
const body = $json.body || $json;

const correlationId = body.correlationId || body.correlation_id || `gp_${Date.now()}`;
const message = body.message || body.summary || 'Golden path smoke';
const serviceName = body.serviceName || body.service_name || body.name || 'hive-golden-path-smoke';

const registerPayload = {
  correlationId,
  jobType: body.jobType || body.job_type || 'hive.golden_path.smoke',
  goal: body.goal || 'G3 smoke-test registration',
  source: body.source || 'hive-golden-path',
  status: body.status || 'healthy',
  registerTo: 'scorpion',
  summary: message,
  metadata: {
    lane: 'hive-os',
    serviceName,
    version: body.version || '1.0.0',
    host: 'evenslouis.ca',
    triggeredAt: new Date().toISOString(),
    telegramRequired: 'false',
    g1Telegram: 'soft-legacy',
    g3Smoke: 'required-legacy'
  }
};

return [{
  json: {
    registerPayload,
    originalInput: body
  }
}];

// Evaluate registration result. Missing Telegram is irrelevant here.
const result = $input.first().json;
const statusCode = result.statusCode || result.code || 200;
const success = statusCode >= 200 && statusCode < 300;
const sent = $('Build Register Payload').first().json.registerPayload;

if (!success) {
  return [{
    json: {
      registered: false,
      statusCode,
      error: result.message || result.error || 'Registration failed',
      hint: 'Watchdog smokes POST https://evenslouis.ca/scorpion/api/hive/register with X-Hive-Secret (existing HIVE_WEBHOOK_SECRET). 401 = operator HITL — do not invent credentials.',
      sentPayload: sent
    }
  }];
}

return [{
  json: {
    registered: true,
    serviceId: result.data?.id || result.id || null,
    correlationId: sent.correlationId,
    message: result.data?.message || result.message || 'OK'
  }
}];
